from pathlib import Path

from pyaraim.testing.refcases import check_reference_cases


def test_shipped_reference_vectors_still_match():
    """Regression guard: tests/reference_cases.json was generated by an earlier run of the code."""
    res = check_reference_cases(Path(__file__).with_name("reference_cases.json"), rtol=1e-6)
    assert res and all(res.values())
